         [\"\240\159\140\177\", \"\240\159\140\177\", \"\240\159\140\177\"],\n\
         [\"\", \"\", \"\"]\n\
         ]\n\
         end;\n\n\
         hint \"select different seed and plant\"\n\
         test\n\
         let m = do(init, [SelectSeed(1), PlantCrop(2, 2)]) in\n\
         m.field == [\n\
